package io.godseed.one;

import android.app.Activity;
import android.os.Bundle;
import android.webkit.WebSettings;
import android.webkit.WebView;

/** Reference implementation of the SDK-free v0.1 Dalvik entrypoint.
 * The debug APK bytecode is generated by build_apk.py. No network permission.
 */
public final class MainActivity extends Activity {
    @Override protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        requestWindowFeature(1); // FEATURE_NO_TITLE
        WebView view = new WebView(this);
        WebSettings options = view.getSettings();
        options.setJavaScriptEnabled(true);
        options.setDomStorageEnabled(true);
        view.loadUrl("file:///android_asset/index.html");
        setContentView(view);
    }
}
